mermaid_flowchart:
flowchart TD
    A[确定基准目标] --> B[识别核心任务];
    B --> C[选择现有文本QA数据集];
    C --> D[将文本QA转换为音频QA];
    D --> E[录制/合成音频];
    E --> F[Human Annotation音频];
    F --> G{Quality Control - 标注一致性}; 
    G -- 不通过 --> F;
    G -- 通过 --> H[Data Cleaning与预处理];
    H --> I[数据格式统一];
    I --> J[构建Evaluation指标];
    J --> K[数据集划分 - 训练/Validation/测试];
    K --> L[Final Dataset组成];
    L --> M[模型Evaluation];
    M --> N[结果分析];
    N --> O[基准发布];
    O --> P[社区反馈与迭代];
    C --> Q[生成逻辑推理问题];
    Q --> E;
    D --> R[音频特征提取];
    R --> S[音频文本对齐];
    S --> F;
